//! The reference client's icon set, compiled into strokeable geometry.
//!
//! **Generated by `tools/gen_icons.py`. Do not edit.**
//!
//! These are the Modrinth App's own icons, out of the SVGs in
//! `vendor/modrinth-app/assets/icons`, and they are outlines rather than
//! pictures: the reference draws them stroked in `currentColor` at width 2
//! with round caps and joins, which is what lets an icon take the colour of
//! the control it sits in. This is why they are geometry and not a bitmap --
//! a rasterised icon cannot be tinted, and the shell's previous icons were
//! bitmaps carved out of another launcher's binary.
//!
//! `assets/icons` is three directories, and so is this file:
//!
//! | table | where | variants | count |
//! | --- | --- | --- | --- |
//! | `ALL` | `icons/` | `none` | 313 |
//! | `TAG_CATEGORIES` | `icons/tags/categories` | `TagCategory` | 102 |
//! | `TAG_LOADERS` | `icons/tags/loaders` | `TagLoader` | 26 |
//!
//! The prefixes are the reference's own. `assets/build/generate-exports.ts`
//! walks the same two tag directories and writes `TagCategory${stem}` and
//! `TagLoader${stem}` because `tags/categories/badge-check.svg` and
//! `badge-check.svg` are two different pictures; the `Icon` suffix it also
//! appends is dropped here because these variants read `BadgeCheck`. Nothing
//! outside a tag set is prefixed, which is what keeps the other names as they
//! were.
//!
//! Four of the 132 tag icons are **not here**, because the generator refuses
//! the construct rather than approximating it. They are named below and in
//! `the_tag_icons_this_tool_could_not_read_are_the_four_it_names`:
//!
//! * `tags/loaders/geyser.svg` -- non-uniform transform scale (1.0404 x 1.1631)
//! * `tags/loaders/legacy-fabric.svg` -- unknown attribute `clip-path` on <g>
//! * `tags/loaders/purpur.svg` -- non-uniform transform scale (1.1250 x 1.1372)
//! * `tags/loaders/quilt.svg` -- non-uniform transform scale (0.0305 x 0.0305)
//!
//! A tag pill for one of those four draws no icon, which makes it the
//! 24-row pill rather than the 26-row one -- the height a tag with no icon
//! has anyway, and not a wrong shape.
//!
//! Arcs, quadratics and the smooth-curve commands are all already converted
//! to cubics by the generator, and `<g transform>` is applied to every point
//! before it is written: an affine map commutes with Bezier evaluation, so
//! transforming the control points transforms the curve exactly.
//!
//! 10 elements are **`Cmd::NoPaint`**: a shape the reference
//! declares with neither a fill nor a stroke, which SVG paints not at all.
//! It is the clamp path every exported icon carries, and it used to be
//! emitted as a stroked outline -- reading `fill="none"` as *unfilled but
//! stroked* -- which drew a 1px frame around ten glyphs. They are named in
//! `the_shapes_the_reference_does_not_paint_are_the_ten_it_names`:
//!
//! * `key.svg` element 1
//! * `loader.svg` element 1
//! * `palette.svg` element 1
//! * `tags/categories/entities.svg` element 1
//! * `tags/categories/mobs.svg` element 1
//! * `tags/loaders/bungeecord.svg` element 1
//! * `tags/loaders/fabric.svg` element 1
//! * `tags/loaders/forge.svg` element 1
//! * `tags/loaders/liteloader.svg` element 1
//! * `tags/loaders/paper.svg` element 1
//!
//! Gate: `python tools/gen_icons.py --check` regenerates and compares bytes.

// Nothing draws these yet: the shell that will is stage 2 of
// `docs/superpowers/specs/2026-09-24-modrinth-native-rewrite.md`, and the shell
// on screen today draws `crate::icons`' carved PNGs. Delete this line the day
// the last icon is drawn from here.
#![allow(dead_code)]

use iced::widget::canvas::{fill::Rule, Fill, LineCap, LineDash, LineJoin, Path, Stroke, Style};
use iced::{Color, Point};

/// One drawing step. Absolute coordinates, in the icon's own view box.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Cmd {
    /// Start a subpath at `(x, y)`.
    Move(f32, f32),
    /// A straight line to `(x, y)`.
    Line(f32, f32),
    /// A cubic Bezier: two control points then the end point.
    Cubic(f32, f32, f32, f32, f32, f32),
    /// Close the current subpath.
    Close,
    /// A shape that declares neither a fill nor a stroke, which SVG paints
    /// not at all. The builder skips it, so the element it belongs to
    /// builds an empty path.
    ///
    /// This is the clamp path every exported icon carries -- `M0 0h24v24H0Z`
    /// with `fill="none"` and no `stroke` -- written out because reading
    /// `fill="none"` as *unfilled but stroked* drew a 24-unit box around
    /// the glyph: a 1px frame the reference does not draw.
    NoPaint,
}

/// Where an element's colour comes from.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Ink {
    /// `currentColor`: the colour of whatever the icon is drawn in, which is
    /// what almost every icon in the set asks for.
    Inherit,
    /// A literal the reference wrote out: a red, a white.
    Fixed(u8, u8, u8, u8),
    /// A `var(--token)` the reference names, to be resolved through
    /// `crate::theme_gen` rather than guessed at here.
    Token(&'static str),
}

impl Ink {
    /// The colour this element is, given what the caller is drawing with.
    pub fn resolve(self, inherit: Color) -> Color {
        match self {
            Ink::Inherit => inherit,
            Ink::Fixed(r, g, b, a) => Color::from_rgba8(r, g, b, a as f32 / 255.0),
            // A token the shell has not been taught yet is drawn in the ink it
            // would have had anyway, which is visible rather than invisible.
            Ink::Token(_) => inherit,
        }
    }
}

/// One drawable piece of an icon: geometry, and how to paint it.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Element {
    /// The geometry, in the icon's view box.
    pub commands: &'static [Cmd],
    /// Stroke width, in view-box units.
    pub stroke_width: f32,
    /// Whether this element is filled rather than stroked.
    pub filled: bool,
    /// Where its colour comes from.
    pub ink: Ink,
    /// Whether the reference fills this element with `fill-rule="evenodd"`.
    ///
    /// It is carried rather than assumed because the two rules differ, and five
    /// of the tag icons depend on it: the gear behind *Data Pack*, *Resource
    /// Pack* and *Vanilla Shader*, and the two faces behind *Mobs* and
    /// *Entities*, all cut their holes with it and are solid blobs filled
    /// non-zero. Both backends tessellate a `Fill` with either rule, so there
    /// is nothing to refuse -- what there was until this was a generator that
    /// knew about the risk and had nowhere to put the answer.
    pub even_odd: bool,
    /// The element's own `opacity`, which multiplies whatever ink it gets.
    ///
    /// The spinner's ring is a quarter opaque, so this is not decoration:
    /// a stroke at full opacity there draws a solid ring instead of a track.
    pub opacity: f32,
}

