/// A path builder that turns one element's commands into a strokeable path.
fn build(commands: &[Cmd]) -> Path {
    Path::new(|builder| {
        for command in commands {
            match *command {
                Cmd::Move(x, y) => builder.move_to(Point::new(x, y)),
                Cmd::Line(x, y) => {
                    builder.line_to(Point::new(x, y));
                }
                Cmd::Cubic(c1x, c1y, c2x, c2y, x, y) => {
                    builder.bezier_curve_to(
                        Point::new(c1x, c1y),
                        Point::new(c2x, c2y),
                        Point::new(x, y),
                    );
                }
                Cmd::Close => builder.close(),
                // A shape with no fill and no stroke has no segments to walk,
                // so there is nothing to hand the builder.
                Cmd::NoPaint => {}
            }
        }
    })
}

/// How one element is painted: stroked in the ink, or filled with it.
///
/// The reference fills a handful of its icons and strokes the rest, so this
/// is a property of the element rather than of the icon.
///
/// `Fill` is the toolkit's own fill rather than a bare `Color` because it
/// carries the rule beside the style, and the five even-odd tag icons are
/// wrong without it. It is the type `Frame::fill` already takes, so a caller
/// that hands it straight over -- which is what both of this crate's
/// callers do -- keeps compiling.
///
/// No `PartialEq`: the toolkit's `Stroke` does not carry one, and nothing
/// needs to compare two painted elements.
///
/// The variant-size allowance: a stroke carries its own dash pattern, cap
/// and join, which is most of a hundred bytes against a fill's sixteen. A
/// `Box` would move that off the stack and buy nothing -- one of these is
/// built per element and handed straight to the frame -- so the size is
/// left where it is and said out loud.
#[allow(clippy::large_enum_variant)]
#[derive(Debug)]
pub enum Paint {
    /// Stroke the path, at the width the reference declares for it.
    Stroke(Stroke<'static>),
    /// Fill the path, with the rule the reference declared for it.
    Fill(Fill),
}

/// One icon, ready to draw: geometry in its own view box, and how to paint it.
///
/// `scale` is the one thing this cannot know -- the reference draws a 24-unit
/// icon at whatever pixel size a control needs, so a caller drawing it at 16px
/// passes two thirds and the stroke scales with it. That is the whole reason
/// these are paths rather than a bitmap: a bitmap has one size.
///
/// Placing the result is the frame's job (`canvas::Frame`'s own `translate` and
/// `scale`), not this function's: a path is rebuilt every frame anyway, and
/// baking a position in here would rebuild it once per position instead.
pub fn parts(glyph: Glyph, scale: f32, inherit: Color) -> Vec<(Path, Paint)> {
    let mut out = Vec::with_capacity(glyph.elements().len());
    for element in glyph.elements() {
        let resolved = element.ink.resolve(inherit);
        let ink = Color {
            a: resolved.a * element.opacity,
            ..resolved
        };
        let path = build(element.commands);
        let paint = if element.filled {
            Paint::Fill(Fill {
                style: Style::Solid(ink),
                rule: if element.even_odd { Rule::EvenOdd } else { Rule::NonZero },
            })
        } else {
            Paint::Stroke(Stroke {
                style: Style::Solid(ink),
                width: element.stroke_width * scale,
                line_cap: LineCap::Round,
                line_join: LineJoin::Round,
                line_dash: LineDash::default(),
            })
        };
        out.push((path, paint));
    }
    out
}

