#[cfg(test)]
mod tests {
    use super::*;

    /// Every icon in the three tables, as `(name, glyph)` pairs.
    fn every() -> Vec<(&'static str, Glyph)> {
        tables()
            .iter()
            .flat_map(|table| table.iter().copied())
            .collect()
    }

    #[test]
    fn the_whole_reference_is_here() {
        // The vendored tree holds 313 top-level SVGs, 102 in
        // `tags/categories` and 30 in `tags/loaders`; a generator that
        // quietly skipped one that it could not parse would leave a hole
        // nothing else notices, so every count is asserted rather than the
        // absence of errors. The two tag counts are 132 less the four named
        // in `the_tag_icons_this_tool_could_not_read_are_the_four_it_names`,
        // which is why that test exists and why it fails when one of them is
        // taught to the parser.
        assert_eq!(ALL.len(), 313);
        assert_eq!(TAG_CATEGORIES.len(), 102);
        assert_eq!(TAG_LOADERS.len(), 26);
        assert_eq!(every().len(), 441, "the variant count moved");
        let mut names: Vec<&str> = every().iter().map(|(n, _)| *n).collect();
        names.sort_unstable();
        let mut unique = names.clone();
        unique.dedup();
        assert_eq!(names, unique, "two icons share a name");
        // And every variant is reachable from a table, which is what makes
        // `name()` and `by_name()` total over the enum rather than over a
        // subset of it.
        for (_, glyph) in every() {
            assert!(!glyph.name().is_empty(), "{glyph:?} is in no table");
            assert_eq!(Glyph::by_name(glyph.name()), Some(glyph));
        }
    }

    #[test]
    fn the_two_tag_sets_carry_the_reference_prefixes() {
        // `assets/build/generate-exports.ts` walks these same two
        // directories and prefixes each stem, because
        // `tags/categories/badge-check.svg` and `badge-check.svg` are two
        // different pictures. The prefix is what keeps the 313 top-level
        // names exactly as they were -- they are referenced by name across
        // the whole tree, and a collision guard that renamed one would be a
        // silent break in every one of them.
        for (name, glyph) in TAG_CATEGORIES {
            assert!(name.starts_with("tags/categories/"), "{name}");
            assert!(
                format!("{glyph:?}").starts_with("TagCategory"),
                "{name} lost its prefix"
            );
        }
        for (name, glyph) in TAG_LOADERS {
            assert!(name.starts_with("tags/loaders/"), "{name}");
            assert!(
                format!("{glyph:?}").starts_with("TagLoader"),
                "{name} lost its prefix"
            );
        }
        // No tag glyph shares a variant with a top-level one, which is the
        // whole reason for the prefix. `badge-check` is the case that
        // proves the guard was reached rather than passed by luck: the
        // reference ships both.
        let top: Vec<String> = ALL.iter().map(|(_, g)| format!("{g:?}")).collect();
        for (_, glyph) in TAG_CATEGORIES.iter().chain(TAG_LOADERS) {
            assert!(
                !top.contains(&format!("{glyph:?}")),
                "{glyph:?} is also a top-level variant"
            );
        }
        let mut clashing: Vec<&str> = vec!["tags/categories/badge-check", "tags/categories/blocks", "tags/categories/cloud", "tags/categories/compass", "tags/categories/crown", "tags/categories/gauge", "tags/categories/globe", "tags/categories/library", "tags/categories/lock", "tags/categories/palette", "tags/categories/pickaxe", "tags/categories/shield", "tags/categories/skull", "tags/categories/square", "tags/categories/users"];
        clashing.sort_unstable();
        let mut actual: Vec<&str> = TAG_CATEGORIES
            .iter()
            .chain(TAG_LOADERS)
            .filter(|(_, glyph)| {
                let stem = glyph.name().rsplit('/').next().unwrap_or_default();
                ALL.iter().any(|(name, _)| {
                    let other = name.rsplit('/').next().unwrap_or(name);
                    other == stem
                })
            })
            .map(|(name, _)| *name)
            .collect();
        actual.sort_unstable();
        assert_eq!(
            actual, clashing,
            "the set of tag icons whose stem is also a top-level icon moved"
        );
        assert!(!actual.is_empty(), "the collision list is empty, so this proves nothing");
        assert_ne!(Glyph::TagCategoryBadgeCheck, Glyph::BadgeCheck);
    }

    #[test]
    fn every_icon_draws_something_finite() {
        for (name, glyph) in every() {
            let elements = glyph.elements();
            assert!(!elements.is_empty(), "{name} has no elements");
            for element in elements {
                assert!(!element.commands.is_empty(), "{name} has an empty element");
                assert!(
                    matches!(element.commands[0], Cmd::Move(..) | Cmd::NoPaint),
                    "{name} does not start by moving"
                );
                for command in element.commands {
                    for value in numbers(*command) {
                        assert!(value.is_finite(), "{name} has a non-finite coordinate");
                        assert!(value.abs() < 1.0e4, "{name} has an absurd coordinate");
                    }
                }
                assert!(element.stroke_width > 0.0, "{name} has no stroke width");
            }
        }
    }

    #[test]
    fn no_command_survived_that_the_toolkit_cannot_draw() {
        // Arcs, quadratics and the smooth-curve forms are converted by the
        // generator; the command set is closed, so this is a statement about
        // the generator not having grown a case nobody taught the builder.
        let variants = [
            Cmd::Move(0.0, 0.0), Cmd::Line(1.0, 1.0),
            Cmd::Cubic(0.0, 0.0, 1.0, 1.0, 2.0, 2.0), Cmd::Close,
            Cmd::NoPaint,
        ];
        assert_eq!(variants.len(), 5);
        for command in variants {
            let _ = build(&[command]);
        }
    }

    #[test]
    fn the_shapes_that_are_not_paths_came_through_whole() {
        // A circle is four cubics and a close after its move, and a rectangle
        // without a corner radius is four lines. Both are asserted because the
        // element-to-command conversion is the part of the generator with no
        // source to compare against: the SVG says `circle`, the file says
        // cubics, and only a count can tell whether all four arrived.
        let circle = Glyph::by_name("circle").expect("the reference has a circle");
        let first = circle.elements()[0];
        assert_eq!(first.commands.len(), 6);
        assert!(matches!(first.commands[0], Cmd::Move(..)));
        assert!(matches!(first.commands[5], Cmd::Close));
    }

    #[test]
    fn the_icon_used_as_a_placeholder_is_still_stroked_the_reference_way() {
        // `loader` is the icon that made the transform handling matter: it
        // declares a stroke width of 23 inside a matrix that scales by 0.0867,
        // which is how a 24-unit icon is stroked at 2. So this asserts the
        // width came out at 2 rather than at 23 -- the failure mode being a
        // path that is correct in shape and eleven times too heavy in ink.
        let loader = Glyph::by_name("loader").expect("the reference has a loader");
        assert_eq!(loader.view_box(), (24.0, 24.0));
        for element in loader.elements() {
            assert!(
                (element.stroke_width - 2.0).abs() < 0.01,
                "loader strokes at {}, not the 2 its own transform scales to",
                element.stroke_width
            );
            assert_eq!(element.ink, Ink::Inherit);
            assert_eq!(element.opacity, 1.0);
        }
    }

    #[test]
    fn the_filled_paths_that_change_without_even_odd_are_the_ones_it_names() {
        // The two fill rules differ only where a filled path has more than one
        // subpath and its subpaths wind the same way: then even-odd cuts a hole
        // that non-zero fills. `Element::even_odd` now carries the rule, so
        // nothing is drawn wrongly -- but the rule is only worth carrying where
        // it changes the picture, and this says which those are, so a sixth
        // icon that needs it upstream fails here instead of quietly becoming
        // one more `Fill` nobody looks at.
        //
        // Five of them, and every one is a tag icon: the gear behind *Data
        // Pack*, *Resource Pack* and *Vanilla Shader* (three files with the same
        // path), and the two faces behind *Mobs* and *Entities*. None of the 313
        // top-level icons is on this list, which is why the top-level fills
        // looked right before this and these five would not have.
        // Every element that declares the rule carries it, which is the half
        // that is checkable from here: the file's own `even_odd` flags against
        // the list the generator wrote down. The key is the icon and the
        // element's index in it -- `Element` does not carry which tag it came
        // from, and adding a field for a test would put a pointer in every one
        // of them.
        let mut expected: Vec<&str> = vec!["cog#0", "tags/categories/entities#2", "tags/categories/mobs#2", "tags/loaders/datapack#0", "tags/loaders/minecraft#0", "tags/loaders/paper#3", "tags/loaders/vanilla#0", "x#0"];
        expected.sort_unstable();
        let mut actual: Vec<String> = Vec::new();
        for (name, glyph) in every() {
            for (index, element) in glyph.elements().iter().enumerate() {
                if element.filled && element.even_odd {
                    actual.push(format!("{name}#{index}"));
                }
            }
        }
        actual.sort_unstable();
        let expected: Vec<&str> = expected;
        let actual: Vec<&str> = actual.iter().map(|s| s.as_str()).collect();
        assert_eq!(actual, expected);
        assert!(!actual.is_empty(), "the list is empty, so this proves nothing");

        // And the five of those eight are the five where the rule changes the
        // picture rather than being a no-op on a single-subpath or a pair wound
        // the other way round. `cog` and `x` carry it and do not need it, which is
        // harmless: the rule is the reference's own and the toolkit honours it,
        // and carrying what a file declares is not an approximation of it.
        let matters: Vec<&str> = vec!["tags/categories/entities#2", "tags/categories/mobs#2", "tags/loaders/datapack#0", "tags/loaders/minecraft#0", "tags/loaders/vanilla#0"];
        for name in &matters {
            assert!(
                expected.contains(name),
                "{name} is not one of the even-odd elements"
            );
        }
        assert_eq!(
            matters.len(), 5,
            "the number of elements the rule actually changes has moved"
        );
    }

    #[test]
    fn the_icons_the_reference_fills_are_filled() {
        // Most of the set is stroked, and a handful are filled. The filled
        // ones are listed because reading `fill` off the shape instead of
        // inheriting it from the root element -- which is where the reference
        // declares it -- strokes their *outlines*, which renders, and looks
        // like a slightly wrong icon rather than like a bug.
        let expected: Vec<&str> = vec!["cloud", "cog", "cube", "images", "online-indicator", "radio-button", "radio-button-checked", "spinner", "tags/categories/entities", "tags/categories/mobs", "tags/categories/palette", "tags/categories/potato", "tags/loaders/babric", "tags/loaders/bta-babric", "tags/loaders/datapack", "tags/loaders/minecraft", "tags/loaders/paper", "tags/loaders/vanilla", "tags/loaders/velocity", "x"];
        let mut actual: Vec<&str> = every()
            .into_iter()
            .filter(|(_, g)| g.elements().iter().any(|e| e.filled))
            .map(|(n, _)| n)
            .collect();
        actual.sort_unstable();
        assert_eq!(actual, expected);
    }

    #[test]
    fn the_shapes_the_reference_does_not_paint_are_the_ten_it_names() {
        // Ten of the icons carry a shape SVG paints *nothing* for: the clamp
        // path an exported icon has so that its drawing area has a name,
        // `M0 0h24v24H0Z`. Seven declare it `fill="none"` with no `stroke`
        // at all, `key.svg` and `palette.svg` write `stroke="none"` beside
        // their `fill="none"`, and `bungeecord.svg` spells it as a
        // `<rect style="fill:none">`.
        //
        // This used to be emitted as a stroked outline -- reading `fill="none"`
        // as *unfilled but stroked* -- which drew a full 24-unit box around
        // each of these glyphs. Measured on the reference's own profile page:
        // *Fabric* and *Forge* carry no frame there, and ours had a 16x16px
        // one around each glyph.
        //
        // The list is the assertion and it is the whole list, so an icon that
        // gains a clamp fails here rather than quietly growing a box. The
        // key is the icon and the element's index in it, as it is for
        // `even_odd`.
        let mut expected: Vec<&str> = vec!["key#0", "loader#0", "palette#0", "tags/categories/entities#0", "tags/categories/mobs#0", "tags/loaders/bungeecord#0", "tags/loaders/fabric#0", "tags/loaders/forge#0", "tags/loaders/liteloader#0", "tags/loaders/paper#0"];
        expected.sort_unstable();
        let mut actual: Vec<String> = Vec::new();
        for (name, glyph) in every() {
            for (index, element) in glyph.elements().iter().enumerate() {
                if matches!(element.commands, [Cmd::NoPaint]) {
                    actual.push(format!("{name}#{index}"));
                }
            }
        }
        actual.sort_unstable();
        assert_eq!(actual, expected, "the shapes that paint nothing moved");
        assert_eq!(expected.len(), 10, "the number of unpainted shapes moved");

        // And none of the ten is the whole of its icon: a glyph that paints
        // nothing at all would be a different picture, and the four tag icons
        // this tool refuses are already absent rather than half-drawn.
        for (name, glyph) in every() {
            let painted = glyph
                .elements()
                .iter()
                .filter(|element| !matches!(element.commands, [Cmd::NoPaint]))
                .count();
            assert!(painted > 0, "{name} paints nothing at all");
        }
    }

    #[test]
    fn the_spinner_ring_keeps_its_opacity() {
        // The one icon in the set that draws at less than full opacity: a
        // 25% track under a 75% head. A generator that dropped the attribute
        // would draw a solid ring, which reads as a finished circle.
        let spinner = Glyph::by_name("spinner").expect("the reference has a spinner");
        let opacities: Vec<f32> = spinner.elements().iter().map(|e| e.opacity).collect();
        assert!(opacities.contains(&0.25), "the track lost its opacity: {opacities:?}");
        assert!(opacities.contains(&0.75), "the head lost its opacity: {opacities:?}");
    }

    #[test]
    fn only_the_icons_that_deviate_from_width_two_do() {
        // Nearly the whole set declares one stroke width, 2, and a handful
        // declare their own because their art is deliberately heavier or
        // finer. The exceptions are written down, so a sixth one appearing
        // upstream fails here rather than silently changing an icon that
        // nothing else compares.
        let mut widths: Vec<String> = every()
            .into_iter()
            .flat_map(|(n, g)| {
                g.elements()
                    .iter()
                    .map(move |e| format!("{n}:{}", e.stroke_width))
            })
            .filter(|entry| {
                // A width that reaches 2 through a transform's scale counts as
                // 2; `loader` does exactly that.
                let width = entry.rsplit(':').next().and_then(|w| w.parse::<f32>().ok());
                match width {
                    Some(value) => (value - 2.0).abs() > 0.01,
                    None => true,
                }
            })
            .collect();
        widths.sort_unstable();
        let expected: Vec<&str> = vec!["page-round:8", "restore:1.6", "restore:1.6", "spinner:4", "tags/categories/colored-lighting:2.3254", "tags/categories/colored-lighting:2.3254", "tags/categories/colored-lighting:2.3254", "tags/categories/high:3", "tags/categories/high:3", "tags/categories/high:3", "tags/categories/high:3", "tags/categories/low:3", "tags/categories/low:3", "tags/categories/medium:3", "tags/categories/medium:3", "tags/categories/medium:3", "tags/categories/path-tracing:2.1986", "tags/categories/path-tracing:2.1986", "tags/categories/path-tracing:2.1986", "tags/loaders/babric:0.25", "tags/loaders/babric:0.25", "tags/loaders/bta-babric:0.25", "tags/loaders/bta-babric:0.25", "tags/loaders/bukkit:24", "tags/loaders/iris:48.8622", "tags/loaders/iris:48.8622", "tags/loaders/neoforge:8.33", "tags/loaders/spigot:24", "tags/loaders/sponge:24", "test:1.5"];
        assert_eq!(
            widths, expected,
            "the set of icons that do not stroke at width 2 has changed"
        );
        assert!(!widths.is_empty(), "the exceptions list is empty, so this proves nothing");
    }

    #[test]
    fn the_tag_icons_this_tool_could_not_read_are_the_four_it_names() {
        // The generator refuses what it cannot model rather than
        // approximating it, and it prints every refusal while it runs -- but a
        // message on a build machine is not a gate. These four are the ones it
        // cannot read, and the reason is written next to each, so that:
        //
        // * a fifth icon appearing in either tag directory fails the build
        //   rather than being skipped into a hole;
        // * teaching the parser the construct fails the build too, which is the
        //   point: the day one of these is drawn it should be because somebody
        //   decided it should be, in a commit that says so.
        //
        // Three are non-uniform transform scales -- `geyser`, `purpur` and
        // `quilt` -- where a round-capped stroke has no single width to apply;
        // one is a `clip-path` the tool cannot put on a path.
        let mut refused: Vec<&str> = vec!["tags/loaders/geyser", "tags/loaders/legacy-fabric", "tags/loaders/purpur", "tags/loaders/quilt"];
        refused.sort_unstable();
        assert_eq!(refused.len(), 4, "the number of refusals moved");
        let here: Vec<&str> = every()
            .into_iter()
            .map(|(name, _)| name)
            .filter(|name| name.starts_with("tags/"))
            .collect();
        for name in &here {
            assert!(*name != "tags/loaders/geyser", "{name} was drawn after all");
            assert!(*name != "tags/loaders/purpur", "{name} was drawn after all");
            assert!(*name != "tags/loaders/quilt", "{name} was drawn after all");
            assert!(
                *name != "tags/loaders/legacy-fabric",
                "{name} was drawn after all"
            );
        }
        // 132 tag icons minus four.
        assert_eq!(here.len(), 128);
    }

    fn numbers(command: Cmd) -> Vec<f32> {
        match command {
            Cmd::Move(x, y) | Cmd::Line(x, y) => vec![x, y],
            Cmd::Cubic(a, b, c, d, e, f) => vec![a, b, c, d, e, f],
            Cmd::Close | Cmd::NoPaint => Vec::new(),
        }
    }
}
